// ---- البوابة ----
// كان هذا الخطّاف مفتوحاً بلا أي حارس: من يعرف العنوان يكتب في قاعدة
// العملاء المحتملين بلا حدّ. وهو مقصود لنداءٍ واحد — الوكيل الصوتي.
//
// والسرّ ليس مكتوباً هنا. يأتي من متغيّر n8n اسمه
// ALMUHALLAB_LEAD_SECRET (Settings → Variables)، فلا يظهر في تصدير
// السير ولا في فروق النسخ، وتدويره تعديلٌ في الواجهة بلا لمس كود.
//
// ويفشل مغلقاً: متغيّرٌ غائب يرفض كل الطلبات ولا يفتح الباب.
const SECRET = String(($vars && $vars.ALMUHALLAB_LEAD_SECRET) || '');
if (!SECRET) throw new Error('server not configured: set the n8n variable ALMUHALLAB_LEAD_SECRET');

const h = $json.headers || {};
const given = String(h['x-lead-secret'] || h['X-Lead-Secret'] || '');
let ok = given.length === SECRET.length;
for (let i = 0; i < SECRET.length; i++) { if (given[i] !== SECRET[i]) ok = false; }
if (!ok) throw new Error('unauthorized');

return [{ json: $json }];
